        rows_str = t[m.end():].split('\n')[:h]
        # Get non-empty lines
        valid_rows = [r for r in rows_str if r.strip()]
        if len(valid_rows) != h and not any('8' in r or '0' in r or '2' in r or '3' in r or '4' in r or '7' in r for r in valid_rows):
            continue
        if len(valid_rows) < h:
            # Try getting next line
            for i in range(len(rows_str), h):
                extra_line = t.split('\n')[i] if i < len(t.split('\n')) else ''
                if extra_line.strip():
                    valid_rows.append(extra_line)
