def solve_transform(grid):
    """Transform grid according to the discovered rules"""
    h, w = len(grid), len(grid[0])

    # Color mapping observed from demo
    color_map = {2: 3, 3: 6, 6: 2}

    result = [[grid[i][j] for j in range(w//2)] for i in range(h)]

    # For each row, find the dominant shape color on the right side
    for i in range(h):
        right_part = [grid[i][j] for j in range(w//2, w)]
        shape_color = next((v for v in right_part if v != 0), None)

        if shape_color is None:
            continue

        mapped_color = color_map.get(shape_color, 0)

        # Find anchor positions: cols where horizontal mirror has non-zero value
        anchors = set()
        mirror_w = w - 1  # Last column index
        for j in range(w//2):
            if result[i][j] == 0:
                mirror_pos = mirror_w - j
                if grid[i][mirror_pos] != 0:
                    anchors.add(j)

        if not anchors:
            continue

        # Fill anchors and expand horizontally to all consecutive zeros
        # First, mark all reachable zeros
        filled = set(anchors)
        changed = True
        while changed:
            changed = False
            for j in range(w//2):
                if j in filled:
                    continue
                if result[i][j] != 0:
                    continue
                # Check if adjacent to any filled cell
                if j > 0 and j - 1 in filled:
                    filled.add(j)
                    changed = True
                if j < w//2 - 1 and j + 1 in filled:
                    filled.add(j)
                    changed = True

        # Apply fill
        for j in sorted(filled):
            result[i][j] = mapped_color

    return result

