def solve_transform_v10(grid):
    """Group by shape, compute union of interiors, fill only zeros"""
    h, w = len(grid), len(grid[0])

    color_map = {2: 3, 3: 6, 6: 2}

    result = [[grid[i][j] for j in range(w//2)] for i in range(h)]

    i = 0
    while i < h:
        start_row_right = [grid[i][c] for c in range(w//2, w)]
        shape_color = next((v for v in start_row_right if v != 0), None)

        if shape_color is None:
            i += 1
            continue

        mapped = color_map.get(shape_color, 0)

        group_rows = []
        r = i
        while r < h:
            row_right = [grid[r][c] for c in range(w//2, w)]
            if not any(v != 0 for v in row_right):
                break
            group_rows.append(r)
            r += 1

        union_start, union_end = None, None

        for gr in group_rows:
            left = [grid[gr][j] for j in range(w//2)]
            first_nonzero = next((j for j, v in enumerate(left) if v != 0), None)
            last_nonzero = next((j for j in range(len(left)-1, -1, -1) if left[j] != 0), None)

            if first_nonzero is not None and last_nonzero is not None:
                start = first_nonzero + 1
                end = last_nonzero - 1

                if union_start is None:
                    union_start = start
                union_end = max(union_end, end) if union_end is not None else end

        if union_start is not None:
            for gr in group_rows:
                for j in range(union_start, union_end + 1):
                    if result[gr][j] == 0:
                        result[gr][j] = mapped

        i = r

    return result

