def solve_transform_v15(grid):
    """Fill entire interior span when any anchor exists"""
    h, w = len(grid), len(grid[0])

    color_map = {2: 3, 3: 6, 6: 2}

    result = [[grid[i][j] for j in range(w//2)] for i in range(h)]

    for i in range(h):
        right_part = [grid[i][c] for c in range(w//2, w)]
        shape_color = next((v for v in right_part if v != 0), None)

        if shape_color is None:
            continue

        mapped = color_map.get(shape_color, shape_color)

        # Find ANY anchors (either direct or mirror)
        anchors_exist = False
        for j in range(w//2):
            if result[i][j] == 0:
                # Direct check
                if grid[i][j + w//2] == shape_color:
                    anchors_exist = True
                    break
                # Mirror check  
                if grid[i][w - 1 - j] == shape_color:
                    anchors_exist = True
                    break

        if not anchors_exist:
            continue

        # Fill ENTIRE interior span (between frame borders)
        first_nonzero = None
        last_nonzero = None
        for j in range(w//2):
            if result[i][j] != 0:
                if first_nonzero is None:
                    first_nonzero = j
                else:
                    last_nonzero = j

        if first_nonzero is not None and last_nonzero is not None:
            start_fill = first_nonzero + 1
            end_fill = last_nonzero - 1

            for j in range(start_fill, end_fill + 1):
                if result[i][j] == 0:
                    result[i][j] = mapped

    return result

