def solve_transform_v16(grid):
    """Vertical-aware: process in groups and propagate"""
    h, w = len(grid), len(grid[0])

    color_map = {2: 3, 3: 6, 6: 2}

    result = [[grid[i][j] for j in range(w//2)] for i in range(h)]

    i = 0
    while i < h:
        # Group consecutive rows with same shape
        group_rows = []
        r = i
        while r < h:
            right_part = [grid[r][c] for c in range(w//2, w)]
            shape_color = next((v for v in right_part if v != 0), None)

            if shape_color is None:
                break

            group_rows.append(r)
            r += 1

        if not group_rows:
            i += 1
            continue

        shape_color = grid[group_rows[0]][w//2]
        mapped = color_map.get(shape_color, shape_color)

        # Find span for FIRST row (anchor-based)
        first_row = group_rows[0]
        anchors = set()
        for j in range(w//2):
            if result[first_row][j] == 0:
                direct_pos = j + w//2
                if grid[first_row][direct_pos] == shape_color:
                    anchors.add(j)

        # Fill from anchors in first row
        filled = set(anchors)
        changed = True
        while changed:
            changed = False
            for j in range(w//2):
                if j not in filled and result[first_row][j] == 0:
                    if j > 0 and j-1 in filled:
                        filled.add(j)
                        changed = True
                    elif j < w//2 - 1 and j+1 in filled:
                        filled.add(j)
                        changed = True

        for j in sorted(filled):
            result[first_row][j] = mapped

        # Propagate to other rows in group
        # Each row can independently find its own anchors and expand
        for gr in group_rows[1:]:
            row_anchors = set()
            for j in range(w//2):
                if result[gr][j] == 0:
                    direct_pos = j + w//2
                    if grid[gr][direct_pos] == shape_color:
                        row_anchors.add(j)

            row_filled = set(row_anchors)
            changed = True
            while changed:
                changed = False
                for j in range(w//2):
                    if j not in row_filled and result[gr][j] == 0:
                        if j > 0 and j-1 in row_filled:
                            row_filled.add(j)
                            changed = True
                        elif j < w//2 - 1 and j+1 in row_filled:
                            row_filled.add(j)
                            changed = True

            for j in sorted(row_filled):
                result[gr][j] = mapped

        # Propagate within group vertically
        for gr_idx in range(len(group_rows)):
            if gr_idx > 0:
                prev = group_rows[gr_idx-1]
                curr = group_rows[gr_idx]
                for j in range(w//2):
                    if result[curr][j] == 0 and result[prev][j] != 0:
                        result[curr][j] = result[prev][j]

        i = r

    return result

